def headers():
    return {"type": "object", "properties": {
        "Content-Type": {"type": "string", "default": "application/json"},
        "Accept": {"type": "string", "default": "application/json"},
        "Authorization": {"type": "string", "default": "Bearer test"}}}


def call_obj():
    return {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}


def api(name, ep, data_props, pre, post, retries, desc="Engine call."):
    t = {"type": "function", "config": {"timeoutMs": 20000, "maxRetries": retries},
         "function": {"name": name, "handler": "__function__:api_call", "description": desc,
                      "parameters": {"type": "object", "properties": {
                          "url": {"type": "string", "default": BASE + ep},
                          "method": {"type": "string", "default": "POST"},
                          "headers": headers(),
                          "body": {"type": "object", "properties": {
                              "data": {"type": "object", "properties": data_props},
                              "call": call_obj()}}}}},
         "post_process_code": post}
    if pre:
        t["pre_process_code"] = pre
    return t


def cond_eq(var, val):
    return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}


def tr(target, var=None, val=None, desc=None):
    if var is None:
        return {"target_node": target, "description": desc or "always", "condition": {"operator": "always"}}
    return {"target_node": target, "description": desc or f"{var} is {val}", "condition": cond_eq(var, val)}


def end(name, fn, msg):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "transitions": [], "terminal": {"type": "function", "function": {"name": fn, "handler": "__function__:end_call",
            "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "custom"},
                                                            "spoken_message": {"type": "string", "default": msg}}}}}}


def code_node(name, code, transitions, nxt):
    return {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": {"type": "silent"},
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                             "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": code},
                                                                             "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": transitions + [tr(nxt)]}


def api_node(name, tool, transitions, nxt, on_enter=None):
    return {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": on_enter or {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [tool], "transitions": transitions + [tr(nxt)]}


def yn(name, desc, extra=None):
    vals = ["yes", "no", "unclear"] + (extra or [])
    return {"name": name, "type": "string", "enum_values": vals, "description": desc, "min_confidence": 0.6}


