def gend(key, fn, msg, intent, extra_excl=()):
    n = end(key, fn, msg)
    n["description"] = intent
    n["condition"] = {"operator": "matches_intent", "description": intent}
    n["excluded_nodes"] = END_KEYS + ENGINE + list(extra_excl)
    return n


