[{'target_node': 'end_no_card', 'description': 'list_state is no_card', 'condition': {'logic': 'or', 'conditions': [{'variable': 'list_state', 'operator': 'equals', 'operand': 'no_card'}]}}, {'target_node': 'end_service_error', 'description': 'list failed', 'condition': {'logic': 'or', 'conditions': [{'variable': 'list_state', 'operator': 'equals', 'operand': 'error'}, {'variable': 'list_state', 'operator': 'equals', 'operand': 'none'}]}}, {'target_node': 'balance_single', 'description': 'card_count is 1', 'condition': {'logic': 'or', 'conditions': [{'variable': 'card_count', 'operator': 'equals', 'operand': '1'}]}}, {'target_node': 'select_card', 'description': 'always', 'condition': {'operator': 'always'}}]

import json, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
def w3(n):
    p = []
    h = n // 100
    r = n % 100
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        p.append(TENS[r // 10])
    if r % 10:
        p.append(ONES[r % 10])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    p = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        g = n // val
        if g:
            if val == 1000 and g == 1:
                p.append('bin')
            else:
                p.append(w3(g) + ' ' + nm)
            n = n % val
    if n:
        p.append(w3(n))
    return ' '.join(p)
def num(x):
    try:
        return float(str(x).replace(',', '.'))
    except Exception:
        return 0.0
def split_amt(x):
    c = int(round(abs(num(x)) * 100))
    return c // 100, c % 100
def amount(x, cur, final=False):
    w, k = split_amt(x)
    W = words(w)
    if cur == 'TL':
        if k:
            return W + ' lira ' + words(k) + (' kuruştur' if final else ' kuruş')
        return W + (" Türk Lirası'dır" if final else ' Türk Lirası')
    if cur == 'GBP':
        if k:
            return W + ' İngiliz Sterlini ' + words(k) + (" peni'dir" if final else ' peni')
        return W + (" İngiliz Sterlini'dir" if final else ' İngiliz Sterlini')
    small = 'dolar' if cur == 'USD' else 'euro'
    big = 'Dolar' if cur == 'USD' else 'Euro'
    if k:
        return W + ' ' + small + ' ' + words(k) + (" sent'tir" if final else ' sent')
    if final:
        return W + ' ' + big + ("'dır" if cur == 'USD' else "'dur")
    return W + ' ' + big
def pdate(s):
    try:
        s = str(s).strip()
        d, m, y = s.split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if not d:
        return str(s)
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def date_cop(s):
    d = pdate(s)
    if not d:
        return str(s)
    y = d.year
    last = y % 10
    if last == 0:
        t = (y % 100) // 10
        suf = ["'dır", "'dur", "'dir", "'dur", "'tır", "'dir", "'tır", "'dir", "'dir", "'dır"][t]
    else:
        suf = ['', "'dir", "'dir", "'tür", "'tür", "'tir", "'dır", "'dir", "'dir", "'dur"][last]
    return sdate(s) + suf
def digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def clean_name(n):
    n = str(n or '').strip()
    if len(n) > 40 or 'talimat' in n.lower() or 'ignore' in n.lower():
        return ''
    return n
def today_of(vars):
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def classify(result):
    if not isinstance(result, dict):
        return 'error', '', dict()
    result.pop('header', None)
    try:
        sc = int(result.get('status_code') or 200)
    except Exception:
        sc = 200
    d = result.get('data')
    if isinstance(d, str):
        try:
            d = json.loads(d)
        except Exception:
            d = None
    if not isinstance(d, dict):
        return 'error', '', dict()
    r = d.get('result')
    if not isinstance(r, dict):
        r = dict()
    rc = str(r.get('returnCode', r.get('code', '')))
    inner = d.get('data')
    if sc >= 400 or rc != '1' or not isinstance(inner, dict) or str(result.get('status', 'success')) not in ('success', ''):
        return 'error', rc, inner if isinstance(inner, dict) else dict()
    return 'ok', rc, inner
def set_out(result, what, say=''):
    o = dict()
    o['what_to_do_next'] = what
    if say:
        o['say_text'] = say
    if isinstance(result, dict):
        result['data'] = o

try:
    st, rc, inner = classify(result)
    raw = json.dumps(result, ensure_ascii=False) if isinstance(result, dict) else str(result)
    if st != 'ok':
        if 'FB_IVR_CHANNEL_102' in raw or rc == 'FB_IVR_CHANNEL_102' or (isinstance(result, dict) and str(result.get('status_code')) == '404') or ' 404' in raw or 'Not Found' in raw:
            vars['list_state'] = 'no_card'
            set_out(result, 'Uygun kart yok. Arayana şunu söyle: Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
        else:
            vars['list_state'] = 'error'
            set_out(result, 'Teknik hata. Arayana şunu söyle: Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.')
    else:
        cards = inner.get('cards') or []
        out = []
        lines = []
        for c in cards:
            if not isinstance(c, dict):
                continue
            if str(c.get('status', 'A')) not in ('A', ''):
                continue
            cn = str(c.get('cardNumber', ''))
            l4 = str(c.get('cardNumberLast4', '') or cn[-4:])
            nm = clean_name(c.get('productName'))
            main = str(c.get('isMainCard', True)).lower() != 'false'
            e = dict()
            e['n'] = cn
            e['l4'] = l4
            e['name'] = nm
            e['main'] = main
            out.append(e)
        for i, e in enumerate(out):
            lines.append(str(i + 1) + ') ad: ' + (e['name'] or '(adsız kart)') + ' | son dört hane: ' + e['l4'] + ' | ilk altı hane: ' + e['n'][:6] + (' | EK KART (seçilemez)' if not e['main'] else ''))
        vars['cards_json'] = json.dumps(out, ensure_ascii=False)
        vars['card_count'] = str(len(out))
        vars['cards_menu'] = '\n'.join(lines)
        names = []
        for e in out:
            if e['main'] and e['name'] and e['name'] not in names:
                names.append(e['name'])
        ex = names[:2]
        if len(ex) == 2:
            q = 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
        elif len(ex) == 1:
            q = 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' diyebilirsiniz.'
        else:
            q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
        vars['select_question'] = q
        vars['all_names'] = ', '.join([e['name'] or ('sonu ' + digits(e['l4']) + ' ile biten kartınız') for e in out if e['main']])
        if len(out) == 0:
            vars['list_state'] = 'no_card'
        else:
            vars['list_state'] = 'ok'
        set_out(result, 'Kart listesi alındı. Kart numaralarını asla okuma.')
except Exception:
    vars['list_state'] = 'error'

